// Runtime of TypeScript clients generated by goapi. This file is the same
// in every client; do not edit it.
//
// It uses only syntax that type stripping erases, so Node, Deno, Bun and
// bundlers run it as it is.

/** A schema the validator and encoder interpret: a model's descriptor. */
export type Schema =
  | StringSchema
  | NumberSchema
  | { readonly kind: "boolean"; readonly enum?: readonly boolean[] }
  | ArraySchema
  | MapSchema
  | ObjectSchema
  | UnionSchema
  | { readonly kind: "all"; readonly of: readonly Schema[] }
  | { readonly kind: "nullable"; readonly of: Schema }
  | { readonly kind: "ref"; readonly to: () => Schema }
  | { readonly kind: "file" }
  | { readonly kind: "any" };

export interface StringSchema {
  readonly kind: "string";
  readonly minLength?: number;
  readonly maxLength?: number;
  readonly pattern?: string;
  readonly format?: string;
  readonly enum?: readonly string[];
}

export interface NumberSchema {
  readonly kind: "number" | "integer";
  readonly minimum?: number;
  readonly maximum?: number;
  readonly exclusiveMinimum?: number;
  readonly exclusiveMaximum?: number;
  readonly multipleOf?: number;
  readonly enum?: readonly number[];
}

export interface ArraySchema {
  readonly kind: "array";
  readonly items: Schema;
  readonly minItems?: number;
  readonly maxItems?: number;
  readonly uniqueItems?: boolean;
}

export interface MapSchema {
  readonly kind: "map";
  readonly values: Schema;
  readonly minProperties?: number;
  readonly maxProperties?: number;
}

export interface ObjectSchema {
  readonly kind: "object";
  readonly properties: Readonly<Record<string, Property>>;
  /** The schema of other properties; false forbids them, absent allows any. */
  readonly additional?: Schema | false;
  readonly minProperties?: number;
  readonly maxProperties?: number;
}

export interface Property {
  readonly schema: Schema;
  readonly required?: boolean;
  /** Sent by the server only: left out of requests, not required in them. */
  readonly readOnly?: boolean;
  /** Sent by the client only: not required in responses. */
  readonly writeOnly?: boolean;
}

export interface UnionSchema {
  readonly kind: "union";
  readonly variants: readonly Schema[];
  /** Exactly one variant must match (oneOf); otherwise at least one. */
  readonly oneOf: boolean;
  /** The property whose value selects the variant, by mapping. */
  readonly discriminator?: string;
  readonly mapping?: Readonly<Record<string, Schema>>;
}

/** Which way a value goes: requests leave out read-only properties. */
export type Direction = "request" | "response";

/** A schema reference, resolved when it is used, so recursive and
 * mutually dependent schemas can refer to each other. */
export function ref(to: () => Schema): Schema {
  return { kind: "ref", to };
}

/** A problem with a value, at a JSON pointer relative to it. */
export interface Issue {
  readonly pointer: string;
  readonly message: string;
}

function resolve(schema: Schema): Schema {
  while (schema.kind === "ref") {
    schema = schema.to();
  }
  return schema;
}

function child(pointer: string, token: string | number): string {
  return pointer + "/" + String(token).replaceAll("~", "~0").replaceAll("/", "~1");
}

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Blob);
}

function typeOf(v: unknown): string {
  if (v === null) {
    return "null";
  }
  if (Array.isArray(v)) {
    return "array";
  }
  if (v instanceof Blob) {
    return "file";
  }
  return typeof v === "object" ? "object" : typeof v;
}

const patterns = new Map<string, RegExp>();

function compile(pattern: string): RegExp {
  let re = patterns.get(pattern);
  if (re === undefined) {
    // JSON Schema patterns are ECMA-262 regular expressions.
    re = new RegExp(pattern, "u");
    patterns.set(pattern, re);
  }
  return re;
}

/** Validates value against schema, as sent in direction; returns the
 * problems found, none for a valid value. Formats are not checked. */
export function validate(schema: Schema, value: unknown, direction: Direction, pointer = ""): Issue[] {
  const issues: Issue[] = [];
  check(schema, value, direction, pointer, issues);
  return issues;
}

function check(schema: Schema, v: unknown, dir: Direction, at: string, out: Issue[]): void {
  const add = (message: string): void => {
    out.push({ pointer: at, message });
  };
  schema = resolve(schema);
  switch (schema.kind) {
    case "any":
      return;
    case "nullable":
      if (v !== null) {
        check(schema.of, v, dir, at, out);
      }
      return;
    case "string": {
      if (typeof v !== "string") {
        return add(`expected string, got ${typeOf(v)}`);
      }
      // Lengths count code points, as JSON Schema does.
      const length = [...v].length;
      if (schema.minLength !== undefined && length < schema.minLength) {
        add(`must be at least ${schema.minLength} characters long`);
      }
      if (schema.maxLength !== undefined && length > schema.maxLength) {
        add(`must be at most ${schema.maxLength} characters long`);
      }
      if (schema.pattern !== undefined && !compile(schema.pattern).test(v)) {
        add(`must match the pattern ${schema.pattern}`);
      }
      if (schema.enum !== undefined && !schema.enum.includes(v)) {
        add(`must be one of ${schema.enum.map((e) => JSON.stringify(e)).join(", ")}`);
      }
      return;
    }
    case "number":
    case "integer": {
      if (typeof v !== "number" || !Number.isFinite(v)) {
        return add(`expected ${schema.kind}, got ${typeOf(v)}`);
      }
      if (schema.kind === "integer" && !Number.isInteger(v)) {
        return add("expected integer, got a fraction");
      }
      if (schema.minimum !== undefined && v < schema.minimum) {
        add(`must be >= ${schema.minimum}`);
      }
      if (schema.maximum !== undefined && v > schema.maximum) {
        add(`must be <= ${schema.maximum}`);
      }
      if (schema.exclusiveMinimum !== undefined && v <= schema.exclusiveMinimum) {
        add(`must be > ${schema.exclusiveMinimum}`);
      }
      if (schema.exclusiveMaximum !== undefined && v >= schema.exclusiveMaximum) {
        add(`must be < ${schema.exclusiveMaximum}`);
      }
      if (schema.multipleOf !== undefined) {
        const q = v / schema.multipleOf;
        if (Math.abs(q - Math.round(q)) > 1e-9) {
          add(`must be a multiple of ${schema.multipleOf}`);
        }
      }
      if (schema.enum !== undefined && !schema.enum.includes(v)) {
        add(`must be one of ${schema.enum.join(", ")}`);
      }
      return;
    }
    case "boolean":
      if (typeof v !== "boolean") {
        return add(`expected boolean, got ${typeOf(v)}`);
      }
      if (schema.enum !== undefined && !schema.enum.includes(v)) {
        add(`must be one of ${schema.enum.join(", ")}`);
      }
      return;
    case "file":
      if (!(v instanceof Blob)) {
        add(`expected a file (Blob), got ${typeOf(v)}`);
      }
      return;
    case "array": {
      if (!Array.isArray(v)) {
        return add(`expected array, got ${typeOf(v)}`);
      }
      if (schema.minItems !== undefined && v.length < schema.minItems) {
        add(`must have at least ${schema.minItems} items`);
      }
      if (schema.maxItems !== undefined && v.length > schema.maxItems) {
        add(`must have at most ${schema.maxItems} items`);
      }
      if (schema.uniqueItems) {
        const seen = new Set<string>();
        for (const item of v) {
          const key = JSON.stringify(item);
          if (seen.has(key)) {
            add("must not have duplicate items");
            break;
          }
          seen.add(key);
        }
      }
      v.forEach((item, i) => check(schema.items, item, dir, child(at, i), out));
      return;
    }
    case "map": {
      if (!isObject(v)) {
        return add(`expected object, got ${typeOf(v)}`);
      }
      countProperties(Object.keys(v).length, schema, add);
      for (const [k, item] of Object.entries(v)) {
        check(schema.values, item, dir, child(at, k), out);
      }
      return;
    }
    case "object": {
      if (!isObject(v)) {
        return add(`expected object, got ${typeOf(v)}`);
      }
      countProperties(Object.keys(v).length, schema, add);
      for (const [name, p] of Object.entries(schema.properties)) {
        const value = v[name];
        if (value === undefined) {
          const needed = p.required && !(dir === "request" && p.readOnly) && !(dir === "response" && p.writeOnly);
          if (needed) {
            out.push({ pointer: child(at, name), message: "required property is missing" });
          }
          continue;
        }
        check(p.schema, value, dir, child(at, name), out);
      }
      for (const [name, value] of Object.entries(v)) {
        if (name in schema.properties || value === undefined) {
          continue;
        }
        if (schema.additional === false) {
          out.push({ pointer: child(at, name), message: "unknown property" });
        } else if (schema.additional !== undefined) {
          check(schema.additional, value, dir, child(at, name), out);
        }
      }
      return;
    }
    case "all":
      for (const s of schema.of) {
        check(s, v, dir, at, out);
      }
      return;
    case "union": {
      const variant = selected(schema, v);
      if (variant !== undefined) {
        check(variant, v, dir, at, out);
        return;
      }
      const matches = schema.variants.filter((s) => validate(s, v, dir).length === 0).length;
      if (matches === 0) {
        add("matches none of the variants");
      } else if (schema.oneOf && matches > 1) {
        add(`matches ${matches} variants, but only one may match`);
      }
      return;
    }
  }
}

function countProperties(n: number, schema: { minProperties?: number; maxProperties?: number }, add: (m: string) => void): void {
  if (schema.minProperties !== undefined && n < schema.minProperties) {
    add(`must have at least ${schema.minProperties} properties`);
  }
  if (schema.maxProperties !== undefined && n > schema.maxProperties) {
    add(`must have at most ${schema.maxProperties} properties`);
  }
}

// selected returns the variant a union's discriminator names, if it has
// one and the value gives a known value for it.
function selected(schema: UnionSchema, v: unknown): Schema | undefined {
  if (schema.discriminator === undefined || schema.mapping === undefined || !isObject(v)) {
    return undefined;
  }
  const key = v[schema.discriminator];
  return typeof key === "string" ? schema.mapping[key] : undefined;
}

/** Returns value as it is sent in direction: without the read-only
 * properties of requests, or the write-only ones of responses, at any
 * depth. Other values are returned as they are. */
export function encode(schema: Schema, value: unknown, direction: Direction): unknown {
  schema = resolve(schema);
  switch (schema.kind) {
    case "nullable":
      return value === null ? null : encode(schema.of, value, direction);
    case "array":
      return Array.isArray(value) ? value.map((item) => encode(schema.items, item, direction)) : value;
    case "map": {
      if (!isObject(value)) {
        return value;
      }
      const out: Record<string, unknown> = {};
      for (const [k, item] of Object.entries(value)) {
        out[k] = encode(schema.values, item, direction);
      }
      return out;
    }
    case "object": {
      if (!isObject(value)) {
        return value;
      }
      const out: Record<string, unknown> = {};
      for (const [name, item] of Object.entries(value)) {
        const p = schema.properties[name];
        if (p === undefined) {
          out[name] = schema.additional ? encode(schema.additional, item, direction) : item;
        } else if (!(direction === "request" && p.readOnly) && !(direction === "response" && p.writeOnly)) {
          out[name] = encode(p.schema, item, direction);
        }
      }
      return out;
    }
    case "all":
      // Each member leaves out its own read-only properties.
      return schema.of.reduce((v, s) => encode(s, v, direction), value);
    case "union": {
      const variant = selected(schema, value) ?? schema.variants.find((s) => validate(s, value, direction).length === 0);
      return variant === undefined ? value : encode(variant, value, direction);
    }
    default:
      return value;
  }
}

// ---- HTTP ----------------------------------------------------------------

/** How a client sends requests. */
export interface ClientOptions {
  /** The server URL, below which paths are sent; the document's first
   * server URL by default. */
  baseUrl?: string;
  /** The fetch function to send with; the global fetch by default. */
  fetch?: typeof fetch;
  /** Headers sent with every request that does not set them. */
  headers?: Record<string, string>;
  /** Check requests before sending them (true by default). */
  validateRequests?: boolean;
  /** Check response bodies and required headers (false by default). */
  validateResponses?: boolean;
}

/** Options of one call. */
export interface CallOptions {
  signal?: AbortSignal;
  /** Headers of this call, over those the client and operation set. */
  headers?: Record<string, string>;
}

/** A credential: a string, or a function returning one, possibly async. */
export type Credential = string | (() => string | Promise<string>);

/** HTTP basic credentials, or a function returning them. */
export type BasicCredential =
  | { username: string; password: string }
  | (() => { username: string; password: string } | Promise<{ username: string; password: string }>);

/** A parameter of an operation: where it is, and how it is serialized. */
export interface ParamSpec {
  readonly key: string;
  readonly name: string;
  readonly in: "path" | "query" | "header" | "cookie" | "querystring";
  readonly style: string;
  readonly explode: boolean;
  readonly shape: "scalar" | "array" | "object";
  /** The parameter is serialized with a media type (content), not in a
   * style: as JSON, as text, or as form fields. */
  readonly content?: Content;
  readonly required?: boolean;
  readonly schema: Schema;
}

/** How a parameter or header with content is written. */
export type Content = "json" | "text" | "form";

export interface BodyMediaSpec {
  readonly mediaType: string;
  readonly kind: "json" | "form" | "multipart" | "parts" | "partstream" | "text" | "binary" | "jsonl" | "sse";
  /** The request property holding a body of this media type. */
  readonly key: string;
  /** The schema of the body, or of each item of a stream. */
  readonly schema: Schema;
  /** How the data of server-sent events is typed, if it is. */
  readonly events?: EventsSpec;
  /** The parts of positional parts (parts, and partstream streams). */
  readonly parts?: PartsSpec;
}

/** How an item of positional parts is a part: a file (a Blob), its text,
 * or its body as JSON, of schema; a Part with the part's headers if part
 * is set. */
export interface PartItemSpec {
  readonly kind: "file" | "text" | "json";
  readonly schema: Schema;
  readonly part?: boolean;
}

/** The encoding of a part: the content types it may have, the first of
 * which it is written with unless it is a range, and the headers it
 * carries. */
export interface PartEncoding {
  readonly contentTypes?: readonly string[];
  readonly headers?: readonly Omit<HeaderSpec, "key">[];
}

/** A body of positional parts (multipart/mixed and the like): the
 * positions of a tuple, by key, and the items of the parts after them,
 * or of all of them; none may follow without item. Encodings apply to
 * the first parts by position, encoding to the others. */
export interface PartsSpec {
  readonly prefix?: readonly (PartItemSpec & { readonly key: string; readonly optional?: boolean })[];
  readonly item?: PartItemSpec;
  readonly minItems?: number;
  readonly maxItems?: number;
  readonly encodings?: readonly PartEncoding[];
  readonly encoding?: PartEncoding;
}

/** The data of typed server-sent events: of one schema, or of one per
 * kind of event, which the event's name selects. Data is JSON, or text
 * for a kind marked so. */
export type EventsSpec =
  | { readonly data: Schema }
  | { readonly kinds: { readonly [event: string]: { readonly schema: Schema; readonly text?: boolean } } };

export interface HeaderSpec {
  readonly key: string;
  readonly name: string;
  readonly required?: boolean;
  readonly array?: boolean;
  readonly content?: Content;
  readonly schema: Schema;
}

export interface ResponseSpec {
  /** "200", a range such as "4XX", or "default". */
  readonly status: string;
  readonly mediaType?: string;
  readonly kind?: "json" | "text" | "binary" | "byteranges" | "parts" | "partstream" | "jsonl" | "sse";
  readonly schema?: Schema;
  /** The parts of positional parts. */
  readonly parts?: PartsSpec;
  /** The schema of each item, for JSON Lines. */
  readonly item?: Schema;
  /** How the data of server-sent events is typed, if it is. */
  readonly events?: EventsSpec;
  readonly headers?: readonly HeaderSpec[];
  /** Several media types share the status: the variant names its own. */
  readonly withContentType?: boolean;
}

export interface SchemeSpec {
  readonly key: string;
  readonly type: "apiKey" | "http" | "oauth2" | "openIdConnect" | "mutualTLS";
  readonly in?: "header" | "query" | "cookie";
  readonly name?: string;
  readonly scheme?: string;
}

/** An operation, as client.ts describes it to send. */
export interface OperationSpec {
  readonly method: string;
  readonly path: string;
  readonly params: readonly ParamSpec[];
  readonly body?: { readonly required: boolean; readonly media: readonly BodyMediaSpec[] };
  readonly responses: readonly ResponseSpec[];
  /** Alternative requirements, each needing all its schemes; none means
   * the operation is not secured, and an empty one allows anonymous use. */
  readonly security?: readonly (readonly SchemeSpec[])[];
}

/** A link of a response, as client.ts describes it: the responses it is
 * followed from, and where the values of the request it leads to come
 * from. */
export interface LinkSpec {
  readonly name: string;
  readonly responses: readonly { readonly status: string; readonly contentType?: string }[];
  readonly values: readonly {
    /** The property of the linked request. */
    readonly key: string;
    readonly expression: string;
    readonly const?: unknown;
    /** Where the value is, with source the key of the header or request
     * property, and pointer a JSON pointer into a body; a constant
     * without. */
    readonly from?: "responseBody" | "responseHeader" | "requestBody" | "request";
    readonly source?: string;
    readonly pointer?: string;
  }[];
}

/** Builds the request a link leads to from resp, a response, and req, the
 * request it answers: what a generated follow method sends. A value
 * that is not there is left out, for the request's validation to report
 * if it is required. */
export function link(spec: LinkSpec, resp: object, req: object): unknown {
  const r = resp as Values;
  const q = req as Values;
  const status = r["status"] as number;
  if (!spec.responses.some((v) => statusMatches(v.status, status) && (v.contentType === undefined || v.contentType === r["contentType"]))) {
    throw new Error(`link ${spec.name}: a ${status} response has no such link`);
  }
  const out: Values = {};
  for (const v of spec.values) {
    let value: unknown;
    switch (v.from) {
      case undefined:
        value = v.const;
        break;
      case "responseBody":
        value = valueAt(r["body"], v.pointer ?? "");
        break;
      case "responseHeader":
        value = (r["headers"] as Values | undefined)?.[v.source ?? ""];
        break;
      case "requestBody":
        value = valueAt(q[v.source ?? ""], v.pointer ?? "");
        break;
      case "request":
        value = q[v.source ?? ""];
        break;
    }
    if (value !== undefined) {
      out[v.key] = value;
    }
  }
  return out;
}

// valueAt returns the value at pointer, a JSON pointer, in v, or undefined.
function valueAt(v: unknown, pointer: string): unknown {
  if (pointer === "") {
    return v;
  }
  for (const raw of pointer.slice(1).split("/")) {
    const tok = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    if (Array.isArray(v)) {
      v = v[Number(tok)];
    } else if (isObject(v)) {
      v = v[tok];
    } else {
      return undefined;
    }
  }
  return v;
}

/** The problem details of an RFC 9457 problem response. */
export interface Problem {
  type?: string;
  title?: string;
  status?: number;
  detail?: string;
  instance?: string;
  errors?: { in?: string; parameter?: string; pointer?: string; detail?: string }[];
  [key: string]: unknown;
}

/** A request that does not match the document, found before it is sent. */
export class InvalidRequestError extends Error {
  readonly issues: readonly (Issue & { in: string; parameter?: string })[];
  constructor(issues: readonly (Issue & { in: string; parameter?: string })[]) {
    super("invalid request: " + issues.map((i) => `${i.parameter ?? i.in}${i.pointer}: ${i.message}`).join("; "));
    this.name = "InvalidRequestError";
    this.issues = issues;
  }
}

/** A response with a status or media type the operation does not declare. */
export class UnexpectedResponseError extends Error {
  readonly status: number;
  readonly headers: Headers;
  /** The beginning of the body. */
  readonly body: string;
  /** The problem details of a problem+json body. */
  readonly problem?: Problem;
  constructor(status: number, headers: Headers, body: string, problem?: Problem) {
    super(`unexpected ${status} response` + (problem?.title ? `: ${problem.title}` : ""));
    this.name = "UnexpectedResponseError";
    this.status = status;
    this.headers = headers;
    this.body = body;
    if (problem !== undefined) {
      this.problem = problem;
    }
  }
}

/** A declared response that cannot be read, or that does not match the
 * document when responses are validated. */
export class InvalidResponseError extends Error {
  readonly status: number;
  readonly issues: readonly Issue[];
  constructor(status: number, message: string, issues: readonly Issue[] = []) {
    super(`invalid ${status} response: ${message}`);
    this.name = "InvalidResponseError";
    this.status = status;
    this.issues = issues;
  }
}

/** No security requirement of the operation has all its credentials. */
export class NoCredentialsError extends Error {
  constructor() {
    super("no credentials for any of the operation's security requirements");
    this.name = "NoCredentialsError";
  }
}

/** A server-sent event, whose data is a T: the text itself, or the JSON
 * value of a typed stream. */
export interface ServerEvent<T = string> {
  event?: string;
  data: T;
  id?: string;
  retry?: number;
}

/** An item of positional parts whose encoding declares headers: its
 * value and the headers of its part. */
export interface Part<T> {
  header: Headers;
  value: T;
}

/** A part of a multipart/byteranges response: the bytes start to end,
 * inclusive, of a representation of size bytes (-1 if unknown), whose
 * media type is contentType. */
export interface ByteRange {
  start: number;
  end: number;
  size: number;
  contentType: string;
  data: Blob;
}

/** An event of a stream of named kinds: its name E says what its data is. */
export interface NamedEvent<E extends string, T> {
  event: E;
  data: T;
  id?: string;
  retry?: number;
}

type Values = Record<string, unknown>;

function text(v: unknown): string {
  if (typeof v === "string") {
    return v;
  }
  if (typeof v === "number" || typeof v === "boolean") {
    return String(v);
  }
  return JSON.stringify(v);
}

// entries returns the properties of an object in order, without the
// absent ones.
function entries(v: unknown): [string, unknown][] {
  return isObject(v) ? Object.entries(v).filter(([, x]) => x !== undefined) : [];
}

// fields flattens an object into bracketed fields, as forms and deepObject
// write them: a[b]=1, an array of scalars repeated, an array of objects
// with indices (a[0][b]=1).
function fields(v: unknown, prefix: string, out: [string, string][]): void {
  for (const [k, x] of entries(v)) {
    const name = prefix === "" ? k : `${prefix}[${k}]`;
    addField(name, x, out);
  }
}

function addField(name: string, x: unknown, out: [string, string][]): void {
  if (x === null) {
    return;
  }
  if (Array.isArray(x)) {
    if (x.some((item) => isObject(item))) {
      x.forEach((item, i) => (isObject(item) ? fields(item, `${name}[${i}]`, out) : item === null ? undefined : out.push([`${name}[${i}]`, text(item)])));
    } else {
      for (const item of x) {
        out.push([name, text(item)]);
      }
    }
  } else if (isObject(x)) {
    fields(x, name, out);
  } else {
    out.push([name, text(x)]);
  }
}

const unreserved = (s: string) => encodeURIComponent(s);

// quoteItem quotes a header list item that has a comma, a quote or
// surrounding spaces, as RFC 9110 lists allow.
function quoteItem(s: string): string {
  if (s.includes(",") || s.includes('"') || s.trim() !== s) {
    return '"' + s.replaceAll("\\", "\\\\").replaceAll('"', '\\"') + '"';
  }
  return s;
}

// simple serializes a value in the simple style, with item applied to
// each piece.
function simple(p: ParamSpec, v: unknown, item: (s: string) => string): string {
  if (p.shape === "array" && Array.isArray(v)) {
    return v.map((x) => item(text(x))).join(",");
  }
  if (p.shape === "object") {
    const parts = entries(v).map(([k, x]) => (p.explode ? `${item(k)}=${item(text(x))}` : `${item(k)},${item(text(x))}`));
    return parts.join(",");
  }
  return item(text(v));
}

// contentText writes the value of a parameter with content as its media
// type has it.
function contentText(content: Content, v: unknown): string {
  switch (content) {
    case "text":
      return text(v);
    case "form": {
      const out: [string, string][] = [];
      fields(v, "", out);
      return new URLSearchParams(out).toString();
    }
  }
  return JSON.stringify(v);
}

function pathValue(p: ParamSpec, v: unknown): string {
  if (p.content !== undefined) {
    return unreserved(contentText(p.content, v));
  }
  switch (p.style) {
    case "label":
      if (p.shape === "array" && Array.isArray(v)) {
        return "." + v.map((x) => unreserved(text(x))).join(p.explode ? "." : ",");
      }
      if (p.shape === "object") {
        const parts = entries(v).map(([k, x]) => (p.explode ? `${unreserved(k)}=${unreserved(text(x))}` : `${unreserved(k)},${unreserved(text(x))}`));
        return "." + parts.join(p.explode ? "." : ",");
      }
      return "." + unreserved(text(v));
    case "matrix": {
      const n = unreserved(p.name);
      if (p.shape === "array" && Array.isArray(v)) {
        return p.explode ? v.map((x) => `;${n}=${unreserved(text(x))}`).join("") : `;${n}=` + v.map((x) => unreserved(text(x))).join(",");
      }
      if (p.shape === "object") {
        return p.explode
          ? entries(v).map(([k, x]) => `;${unreserved(k)}=${unreserved(text(x))}`).join("")
          : `;${n}=` + entries(v).map(([k, x]) => `${unreserved(k)},${unreserved(text(x))}`).join(",");
      }
      return `;${n}=${unreserved(text(v))}`;
    }
    default:
      return simple(p, v, unreserved);
  }
}

function queryValue(q: URLSearchParams, p: ParamSpec, v: unknown): void {
  if (p.content !== undefined) {
    q.append(p.name, contentText(p.content, v));
    return;
  }
  if (p.style === "deepObject") {
    const out: [string, string][] = [];
    fields(v, p.name, out);
    for (const [k, x] of out) {
      q.append(k, x);
    }
    return;
  }
  if (p.shape === "array" && Array.isArray(v)) {
    const items = v.map(text);
    if (p.style === "form" && p.explode) {
      for (const item of items) {
        q.append(p.name, item);
      }
    } else {
      q.append(p.name, items.join({ spaceDelimited: " ", pipeDelimited: "|" }[p.style] ?? ","));
    }
    return;
  }
  if (p.shape === "object") {
    if (p.explode) {
      for (const [k, x] of entries(v)) {
        q.append(k, text(x));
      }
    } else {
      q.append(p.name, entries(v).flatMap(([k, x]) => [k, text(x)]).join(","));
    }
    return;
  }
  q.append(p.name, text(v));
}

/** The parts of a request being built. */
interface Built {
  path: string;
  query: URLSearchParams;
  rawQuery?: string;
  headers: Headers;
  cookies: string[];
  body?: BodyInit;
  /** The body is a stream, which fetch sends as it is read. */
  streamed?: boolean;
  /** Why the stream failed: fetch reports it as an error of its own. */
  failure?: unknown;
}

function buildParams(op: OperationSpec, req: Values, b: Built): void {
  let path = op.path;
  for (const p of op.params) {
    const v = req[p.key];
    if (p.in === "path") {
      path = path.replace(`{${p.name}}`, pathValue(p, v));
      continue;
    }
    if (v === undefined) {
      continue;
    }
    switch (p.in) {
      case "query":
        queryValue(b.query, p, v);
        break;
      case "querystring":
        if (p.content === "json") {
          b.rawQuery = encodeURIComponent(JSON.stringify(v));
        } else {
          const out: [string, string][] = [];
          fields(v, "", out);
          for (const [k, x] of out) {
            b.query.append(k, x);
          }
        }
        break;
      case "header":
        // Only the items of a list are quoted: a scalar, such as a Range
        // of several ranges, is sent as it is, as the Go client does.
        b.headers.set(p.name, p.content !== undefined ? contentText(p.content, v) : p.shape === "scalar" ? text(v) : simple(p, v, quoteItem));
        break;
      case "cookie":
        if (p.content !== undefined) {
          b.cookies.push(`${p.name}=${encodeURIComponent(contentText(p.content, v))}`);
        } else if (p.shape === "array" && Array.isArray(v) && p.explode) {
          for (const x of v) {
            b.cookies.push(`${p.name}=${encodeURIComponent(text(x))}`);
          }
        } else if (p.shape === "object" && p.explode) {
          for (const [k, x] of entries(v)) {
            b.cookies.push(`${k}=${encodeURIComponent(text(x))}`);
          }
        } else {
          b.cookies.push(`${p.name}=${simple(p, v, encodeURIComponent)}`);
        }
        break;
    }
  }
  b.path = path;
}

function fileName(v: Blob): string | undefined {
  return typeof File !== "undefined" && v instanceof File ? v.name : undefined;
}

// buildBody sets the body of b; checkItems says to validate the items of a
// stream, which checkRequest leaves to it.
function buildBody(op: OperationSpec, req: Values, b: Built, checkItems: boolean): void {
  const body = op.body;
  if (body === undefined) {
    return;
  }
  const contentType = typeof req["contentType"] === "string" ? req["contentType"] : undefined;
  const media =
    body.media.find((m) => m.mediaType === contentType) ??
    body.media.find((m) => req[m.key] !== undefined && contentType === undefined);
  if (media === undefined) {
    return;
  }
  const v = req[media.key];
  if (v === undefined) {
    return;
  }
  switch (media.kind) {
    case "json":
      b.headers.set("Content-Type", media.mediaType);
      b.body = JSON.stringify(encode(media.schema, v, "request"));
      break;
    case "form": {
      const out: [string, string][] = [];
      fields(encode(media.schema, v, "request"), "", out);
      b.headers.set("Content-Type", media.mediaType);
      b.body = new URLSearchParams(out).toString();
      break;
    }
    case "multipart": {
      // fetch writes the content type, with the boundary.
      const form = new FormData();
      for (const [k, x] of entries(encode(media.schema, v, "request"))) {
        for (const item of Array.isArray(x) ? x : [x]) {
          if (item instanceof Blob) {
            const name = fileName(item);
            if (name === undefined) {
              form.append(k, item);
            } else {
              form.append(k, item, name);
            }
          } else if (isObject(item) || Array.isArray(item)) {
            // As a string: FormData names every Blob part a file, and a
            // server reads files apart from fields. The value is JSON,
            // which objects in multipart bodies are by default.
            form.append(k, JSON.stringify(item));
          } else if (item !== null) {
            form.append(k, text(item));
          }
        }
      }
      b.body = form;
      break;
    }
    case "text":
      b.headers.set("Content-Type", media.mediaType.includes("charset=") ? media.mediaType : media.mediaType + "; charset=utf-8");
      b.body = text(v);
      break;
    case "binary":
      b.headers.set("Content-Type", v instanceof Blob && v.type !== "" && media.mediaType.includes("*") ? v.type : media.mediaType);
      b.body = v as BodyInit;
      break;
    case "parts": {
      const spec = media.parts!;
      const boundary = newBoundary();
      const items = partItems(spec, v);
      const chunks = items.flatMap((item, i) => partChunks(spec, item, i, boundary));
      b.headers.set("Content-Type", `${media.mediaType}; boundary=${boundary}`);
      b.body = new Blob([...chunks, partsEnd(items.length, boundary)]);
      break;
    }
    case "partstream": {
      const spec = media.parts!;
      const boundary = newBoundary();
      b.headers.set("Content-Type", `${media.mediaType}; boundary=${boundary}`);
      const item = (x: unknown, i: number): PartItem => {
        const it = { spec: spec.item!, value: x };
        if (checkItems) {
          const issues = partIssues(spec, it, i).map((x) => ({ ...x, in: "body" }));
          if (issues.length > 0) {
            throw new InvalidRequestError(issues);
          }
        }
        return it;
      };
      if (typeof v === "object" && v !== null && Symbol.asyncIterator in v) {
        b.body = itemStream(v as AsyncIterable<unknown>, (x, i) => joinChunks(partChunks(spec, item(x, i), i, boundary)), b, (n) => partsEnd(n, boundary));
        b.streamed = true;
      } else {
        const chunks: BlobPart[] = [];
        let i = 0;
        for (const x of v as Iterable<unknown>) {
          chunks.push(...partChunks(spec, item(x, i), i, boundary));
          i++;
        }
        b.body = new Blob([...chunks, partsEnd(i, boundary)]);
      }
      break;
    }
    case "jsonl":
    case "sse": {
      b.headers.set("Content-Type", media.mediaType);
      const line =
        media.kind === "jsonl"
          ? jsonLine(media.schema, checkItems)
          : (ev: unknown, i: number) => eventText(media.events === undefined ? (ev as ServerEvent) : typedEvent(media.events, ev as ServerEvent<unknown>, i, checkItems));
      if (typeof v === "object" && v !== null && Symbol.asyncIterator in v) {
        b.body = itemStream(v as AsyncIterable<unknown>, line, b);
        b.streamed = true;
      } else {
        // An Iterable, such as an array, is sent at once, which every
        // fetch can do.
        let out = "";
        let i = 0;
        for (const item of v as Iterable<unknown>) {
          out += line(item, i++);
        }
        b.body = out;
      }
      break;
    }
  }
}

// jsonLine returns a function writing an item of a JSON Lines body,
// validating it first if checkItems is set.
function jsonLine(schema: Schema, checkItems: boolean): (item: unknown, i: number) => string {
  return (item, i) => {
    if (checkItems) {
      const issues = validate(schema, item, "request", `/${i}`).map((x) => ({ ...x, in: "body" }));
      if (issues.length > 0) {
        throw new InvalidRequestError(issues);
      }
    }
    return JSON.stringify(encode(schema, item, "request")) + "\n";
  };
}

// eventsSchema returns the schema of the data of ev and whether that data
// is text, or why it has none.
function eventsSchema(spec: EventsSpec, name: string | undefined): { schema: Schema; text: boolean } | string {
  if ("data" in spec) {
    return { schema: spec.data, text: false };
  }
  const kind = name === undefined ? undefined : spec.kinds[name];
  if (kind === undefined) {
    return `unknown event ${JSON.stringify(name ?? "")}; expected ${Object.keys(spec.kinds).map((k) => JSON.stringify(k)).join(", ")}`;
  }
  return { schema: kind.schema, text: kind.text === true };
}

// typedEvent returns ev, the i-th event of a request, with its data
// written as its kind says, validating it first if checkItems is set.
function typedEvent(spec: EventsSpec, ev: ServerEvent<unknown>, i: number, checkItems: boolean): ServerEvent {
  const kind = eventsSchema(spec, ev.event);
  if (typeof kind === "string") {
    throw new InvalidRequestError([{ in: "body", pointer: `/${i}/event`, message: kind }]);
  }
  if (checkItems) {
    const issues = validate(kind.schema, ev.data, "request", `/${i}/data`).map((x) => ({ ...x, in: "body" }));
    if (issues.length > 0) {
      throw new InvalidRequestError(issues);
    }
  }
  return { ...ev, data: kind.text ? text(ev.data) : JSON.stringify(encode(kind.schema, ev.data, "request")) };
}

// eventText writes an event in the text/event-stream format. Line ends in
// its id and name, which would start other fields, are sent as spaces.
function eventText(ev: ServerEvent): string {
  const oneLine = (s: string) => s.replace(/\r\n|\r|\n/g, " ");
  let out = "";
  if (ev.id !== undefined && ev.id !== "") {
    out += `id: ${oneLine(ev.id)}\n`;
  }
  if (ev.event !== undefined && ev.event !== "") {
    out += `event: ${oneLine(ev.event)}\n`;
  }
  if (ev.retry !== undefined && ev.retry > 0) {
    out += `retry: ${Math.floor(ev.retry)}\n`;
  }
  for (const l of ev.data.split(/\r\n|\r|\n/)) {
    out += `data: ${l}\n`;
  }
  return out + "\n";
}

// itemStream is a body that writes the items as fetch reads it, and then
// end, given how many there were. An item that cannot be written, or an
// error of the iterator, fails the request with that error, recorded in b.
function itemStream(
  items: AsyncIterable<unknown>,
  line: (item: unknown, i: number) => string | Promise<Uint8Array>,
  b: Built,
  end?: (n: number) => string,
): ReadableStream<Uint8Array> {
  const it = items[Symbol.asyncIterator]();
  const encoder = new TextEncoder();
  let i = 0;
  return new ReadableStream<Uint8Array>({
    async pull(controller) {
      try {
        const next = await it.next();
        if (next.done === true) {
          if (end !== undefined) {
            controller.enqueue(encoder.encode(end(i)));
          }
          controller.close();
          return;
        }
        const chunk = await line(next.value, i++);
        controller.enqueue(typeof chunk === "string" ? encoder.encode(chunk) : chunk);
      } catch (e) {
        b.failure = e;
        controller.error(e);
      }
    },
    async cancel() {
      await it.return?.();
    },
  });
}

// newBoundary returns a boundary for a multipart body, random as
// mime/multipart makes them.
function newBoundary(): string {
  return Array.from(crypto.getRandomValues(new Uint8Array(30)), (x) => x.toString(16).padStart(2, "0")).join("");
}

/** An item of positional parts, and how it is a part. */
interface PartItem {
  readonly spec: PartItemSpec;
  readonly value: unknown;
}

// encodingAt returns the encoding of the part at index i.
function encodingAt(spec: PartsSpec, i: number): PartEncoding {
  return spec.encodings !== undefined && i < spec.encodings.length ? spec.encodings[i]! : (spec.encoding ?? {});
}

// partItems returns the parts of v, a body of positional parts, in order:
// the items of an array, or the set positions of a tuple and its rest. A
// position set after one that is not cannot be sent.
function partItems(spec: PartsSpec, v: unknown): PartItem[] {
  if (spec.prefix === undefined) {
    return (v as unknown[]).map((value) => ({ spec: spec.item!, value }));
  }
  const tuple = v as Values;
  const items: PartItem[] = [];
  let gap: number | undefined;
  spec.prefix.forEach((p, n) => {
    if (tuple[p.key] === undefined) {
      gap ??= n;
    } else if (gap !== undefined) {
      throw new InvalidRequestError([{ in: "body", pointer: `/${n}`, message: `part ${n} is set, but part ${gap} before it is not` }]);
    } else {
      items.push({ spec: p, value: tuple[p.key] });
    }
  });
  const rest = (tuple["rest"] as unknown[] | undefined) ?? [];
  if (spec.item !== undefined && rest.length > 0) {
    if (gap !== undefined) {
      throw new InvalidRequestError([{ in: "body", pointer: `/${spec.prefix.length}`, message: `parts after ${spec.prefix.length - 1} are set, but part ${gap} is not` }]);
    }
    items.push(...rest.map((value) => ({ spec: spec.item!, value })));
  }
  return items;
}

// partIssues checks item, the part at index i, against its schema and the
// headers its encoding declares.
function partIssues(spec: PartsSpec, item: PartItem, i: number): Issue[] {
  const part = item.spec.part ? (item.value as Part<unknown>) : undefined;
  const issues = validate(item.spec.schema, part !== undefined ? part.value : item.value, "request", `/${i}`);
  return [...issues, ...headerIssues(encodingAt(spec, i), part?.header, `/${i}`, "request")];
}

// partsIssues checks a body of positional parts: its count, each part,
// and the positions of a tuple that are required.
function partsIssues(spec: PartsSpec, v: unknown): Issue[] {
  const missing: Issue[] = [];
  spec.prefix?.forEach((p, n) => {
    if (!p.optional && (v as Values)[p.key] === undefined) {
      missing.push({ pointer: `/${n}`, message: "part is missing" });
    }
  });
  let items: PartItem[];
  try {
    items = partItems(spec, v);
  } catch (e) {
    // A missing part says more than the gap it leaves.
    return missing.length > 0 ? missing : e instanceof InvalidRequestError ? [...e.issues] : [{ pointer: "", message: String(e) }];
  }
  const issues = [...validate(countSchema(spec), items, "request"), ...missing];
  items.forEach((item, i) => issues.push(...partIssues(spec, item, i)));
  return issues;
}

// countSchema is a schema of an array of as many items as the parts may
// be.
function countSchema(spec: PartsSpec): Schema {
  const schema: { -readonly [K in keyof ArraySchema]: ArraySchema[K] } = { kind: "array", items: { kind: "any" } };
  if (spec.minItems !== undefined) {
    schema.minItems = spec.minItems;
  }
  if (spec.maxItems !== undefined) {
    schema.maxItems = spec.maxItems;
  }
  return schema;
}

// headerIssues checks the headers of a part, at the given pointer,
// against those enc declares.
function headerIssues(enc: PartEncoding, header: Headers | undefined, at: string, dir: Direction): Issue[] {
  const issues: Issue[] = [];
  for (const h of enc.headers ?? []) {
    const raw = header?.get(h.name) ?? null;
    if (raw === null) {
      if (h.required) {
        issues.push({ pointer: at, message: `part header ${JSON.stringify(h.name)} is missing` });
      }
      continue;
    }
    let value: unknown;
    try {
      value = headerValue({ key: "", ...h }, raw);
    } catch (e) {
      issues.push({ pointer: at, message: `part header ${JSON.stringify(h.name)}: ${String(e)}` });
      continue;
    }
    for (const x of validate(h.schema, value, dir)) {
      issues.push({ pointer: at, message: `part header ${JSON.stringify(h.name)}: ${x.message}` });
    }
  }
  return issues;
}

// partChunks returns the delimiter, headers and data of item, the part at
// index i of a body with boundary. A part has the first content type its
// encoding names, else the file's own, text/plain or application/json,
// and its length, so that a reader can take it before the next one.
function partChunks(spec: PartsSpec, item: PartItem, i: number, boundary: string): BlobPart[] {
  const part = item.spec.part ? (item.value as Part<unknown>) : undefined;
  const value = part !== undefined ? part.value : item.value;
  const header = new Headers(part?.header);
  const encoder = new TextEncoder();
  let data: Blob | Uint8Array<ArrayBuffer>;
  let type: string;
  switch (item.spec.kind) {
    case "file": {
      data = value as Blob;
      type = data.type !== "" ? data.type : "application/octet-stream";
      const name = fileName(data);
      if (name !== undefined && !header.has("Content-Disposition")) {
        header.set("Content-Disposition", `attachment; filename="${name.replace(/[\\"]/g, "\\$&")}"`);
      }
      break;
    }
    case "text":
      data = encoder.encode(text(value));
      type = "text/plain; charset=utf-8";
      break;
    default:
      data = encoder.encode(JSON.stringify(encode(item.spec.schema, value, "request")));
      type = "application/json";
  }
  const declared = encodingAt(spec, i).contentTypes?.[0];
  if (declared !== undefined && !declared.includes("*")) {
    type = declared;
  }
  header.set("Content-Type", type);
  header.set("Content-Length", String(data instanceof Blob ? data.size : data.byteLength));
  let head = (i === 0 ? "" : "\r\n") + `--${boundary}\r\n`;
  for (const [k, v] of header) {
    head += `${k}: ${v}\r\n`;
  }
  return [head + "\r\n", data];
}

// partsEnd is the end of a body of n parts with boundary.
function partsEnd(n: number, boundary: string): string {
  return (n === 0 ? "" : "\r\n") + `--${boundary}--\r\n`;
}

// joinChunks returns the bytes of chunks, for a stream.
async function joinChunks(chunks: BlobPart[]): Promise<Uint8Array> {
  return new Uint8Array(await new Blob(chunks).arrayBuffer());
}

// check validates the parameters and body of a request, as the server
// would, reporting where each problem is.
function checkRequest(op: OperationSpec, req: Values): void {
  const issues: (Issue & { in: string; parameter?: string })[] = [];
  for (const p of op.params) {
    const v = req[p.key];
    if (v === undefined) {
      if (p.required) {
        issues.push({ in: p.in, parameter: p.name, pointer: "", message: "required parameter is missing" });
      }
      continue;
    }
    for (const i of validate(p.schema, v, "request")) {
      issues.push({ ...i, in: p.in, parameter: p.name });
    }
  }
  if (op.body !== undefined) {
    const given = op.body.media.filter((m) => req[m.key] !== undefined);
    if (given.length === 0 && op.body.required) {
      issues.push({ in: "body", pointer: "", message: "the request body is missing" });
    }
    // The items of a stream are checked as they are written.
    for (const m of given.filter((m, i, all) => all.findIndex((n) => n.key === m.key) === i && m.kind !== "jsonl" && m.kind !== "sse" && m.kind !== "partstream")) {
      const found = m.kind === "parts" ? partsIssues(m.parts!, req[m.key]) : validate(m.schema, req[m.key], "request");
      for (const i of found) {
        issues.push({ ...i, in: "body" });
      }
    }
  }
  if (issues.length > 0) {
    throw new InvalidRequestError(issues);
  }
}

async function credential(c: Credential): Promise<string> {
  return typeof c === "string" ? c : await c();
}

// authorize applies the first security requirement whose credentials are
// all given.
async function authorize(op: OperationSpec, creds: Values, b: Built): Promise<void> {
  if (op.security === undefined || op.security.length === 0) {
    return;
  }
  for (const req of op.security) {
    if (!req.every((s) => creds[s.key] !== undefined && creds[s.key] !== false)) {
      continue;
    }
    for (const s of req) {
      const c = creds[s.key];
      if (s.type === "apiKey") {
        const key = await credential(c as Credential);
        if (s.in === "query") {
          b.query.set(s.name ?? "", key);
        } else if (s.in === "cookie") {
          b.cookies.push(`${s.name}=${encodeURIComponent(key)}`);
        } else {
          b.headers.set(s.name ?? "", key);
        }
      } else if (s.type === "http" && s.scheme === "basic") {
        const { username, password } = typeof c === "function" ? await (c as () => Promise<{ username: string; password: string }>)() : (c as { username: string; password: string });
        const bytes = new TextEncoder().encode(`${username}:${password}`);
        b.headers.set("Authorization", "Basic " + btoa(String.fromCharCode(...bytes)));
      } else if (s.type !== "mutualTLS") {
        const scheme = s.type === "http" && s.scheme !== undefined && s.scheme !== "bearer" ? s.scheme[0]!.toUpperCase() + s.scheme.slice(1) : "Bearer";
        b.headers.set("Authorization", `${scheme} ${await credential(c as Credential)}`);
      }
    }
    return;
  }
  throw new NoCredentialsError();
}

/** The parts of a client a call needs. */
export interface Config {
  readonly baseUrl: string;
  readonly fetch: typeof fetch;
  readonly headers: Record<string, string>;
  readonly validateRequests: boolean;
  readonly validateResponses: boolean;
  readonly credentials: Values;
}

/** Makes the configuration of a client from its options. */
export function config(options: ClientOptions, defaultBaseUrl: string, credentials: object | undefined): Config {
  const baseUrl = options.baseUrl ?? defaultBaseUrl;
  if (baseUrl === "") {
    throw new Error("the document has no absolute server URL: give baseUrl");
  }
  return {
    baseUrl: baseUrl.replace(/\/+$/, ""),
    fetch: options.fetch ?? ((input, init) => fetch(input, init)),
    headers: options.headers ?? {},
    validateRequests: options.validateRequests ?? true,
    validateResponses: options.validateResponses ?? false,
    credentials: (credentials ?? {}) as Values,
  };
}

/** Sends a request of op and reads its response: what a generated method
 * does. */
export async function send(cfg: Config, op: OperationSpec, req: object, call: CallOptions = {}): Promise<unknown> {
  const values = req as Values;
  if (cfg.validateRequests) {
    checkRequest(op, values);
  }
  const b: Built = { path: "", query: new URLSearchParams(), headers: new Headers(), cookies: [] };
  buildParams(op, values, b);
  buildBody(op, values, b, cfg.validateRequests);
  await authorize(op, cfg.credentials, b);
  const accept = [...new Set(op.responses.flatMap((r) => (r.mediaType ? [r.mediaType] : [])))];
  if (accept.length > 0) {
    b.headers.set("Accept", accept.join(", "));
  }
  for (const [k, v] of Object.entries(cfg.headers)) {
    if (!b.headers.has(k)) {
      b.headers.set(k, v);
    }
  }
  // A call's own headers win, so it can ask for another media type.
  for (const [k, v] of Object.entries(call.headers ?? {})) {
    b.headers.set(k, v);
  }
  if (b.cookies.length > 0) {
    // Browsers do not let scripts set Cookie; elsewhere it is sent.
    b.headers.set("Cookie", b.cookies.join("; "));
  }
  const query = b.rawQuery ?? b.query.toString();
  const url = cfg.baseUrl + b.path + (query === "" ? "" : "?" + query);
  const init: RequestInit = { method: op.method, headers: b.headers };
  if (b.body !== undefined) {
    init.body = b.body;
  }
  if (b.streamed === true) {
    // Required to send a stream; not yet in every RequestInit type.
    Object.assign(init, { duplex: "half" });
  }
  if (call.signal !== undefined) {
    init.signal = call.signal;
  }
  let resp: Response;
  try {
    resp = await cfg.fetch(url, init);
  } catch (e) {
    throw b.failure ?? e;
  }
  return readResponse(cfg, op, resp);
}

// mediaType returns the media type of a response, lower case, without
// parameters.
function mediaType(resp: Response): string {
  return (resp.headers.get("Content-Type") ?? "").split(";")[0]!.trim().toLowerCase();
}

function statusMatches(declared: string, status: number): boolean {
  if (declared === "default") {
    return true;
  }
  if (declared.endsWith("XX")) {
    return String(status)[0] === declared[0];
  }
  return Number(declared) === status;
}

function mediaMatches(declared: string, actual: string): boolean {
  const d = declared.split(";")[0]!.trim().toLowerCase();
  if (d === "*/*" || d === actual) {
    return true;
  }
  return d.endsWith("/*") && actual.startsWith(d.slice(0, -1));
}

// pick returns the declared response resp is: exact statuses first, then
// ranges, then default, with a matching media type.
function pick(op: OperationSpec, resp: Response): ResponseSpec | undefined {
  const rank = (s: string) => (s === "default" ? 2 : s.endsWith("XX") ? 1 : 0);
  const mt = mediaType(resp);
  const candidates = op.responses.filter((r) => statusMatches(r.status, resp.status)).sort((a, b) => rank(a.status) - rank(b.status));
  return candidates.find((r) => {
    if (r.mediaType === undefined) {
      return true;
    }
    // A response without a media type is the only one of its status.
    return mt === "" ? candidates.filter((c) => c.status === r.status).length === 1 : mediaMatches(r.mediaType, mt);
  });
}

async function unexpected(resp: Response): Promise<UnexpectedResponseError> {
  const body = (await resp.text()).slice(0, 64 << 10);
  let problem: Problem | undefined;
  if (mediaType(resp).endsWith("problem+json")) {
    try {
      problem = JSON.parse(body) as Problem;
    } catch {
      // Not JSON after all: the body says what there is.
    }
  }
  return new UnexpectedResponseError(resp.status, resp.headers, body, problem);
}

function headerValue(h: HeaderSpec, raw: string): unknown {
  switch (h.content) {
    case "json":
      return JSON.parse(raw);
    case "text":
      return scalarValue(h.schema, raw);
    case "form":
      return formValue(h.schema, raw);
  }
  return h.array ? raw.split(",").map((s) => scalarValue(h.schema, s.trim())) : scalarValue(h.schema, raw.trim());
}

// scalarValue converts text to the primitive value schema describes (or
// the items of an array schema): numbers and booleans by their text, and
// anything else as the text, for validation to check.
function scalarValue(schema: Schema, s: string): unknown {
  while (schema.kind === "ref" || schema.kind === "nullable" || schema.kind === "array") {
    schema = schema.kind === "ref" ? schema.to() : schema.kind === "nullable" ? schema.of : schema.items;
  }
  switch (schema.kind) {
    case "integer":
    case "number":
      return Number(s);
    case "boolean":
      return s === "true" ? true : s === "false" ? false : s;
  }
  return s;
}

// formValue reads an object written as form fields, the inverse of
// fields: a[b]=1 is a nested property, a repeated field an array, and
// a[0][b]=1 an item of an array of objects. Values are converted by the
// schema.
function formValue(schema: Schema, raw: string): Values {
  const out: Values = {};
  for (const [name, value] of new URLSearchParams(raw)) {
    const open = name.indexOf("[");
    const path = open < 0 ? [name] : [name.slice(0, open), ...Array.from(name.slice(open).matchAll(/\[([^\]]*)\]/g), (m) => m[1] ?? "")];
    setField(out, schema, path, value);
  }
  return out;
}

function setField(container: Values, schema: Schema, path: readonly string[], value: string): void {
  let s = resolve(schema);
  if (s.kind === "nullable") {
    s = resolve(s.of);
  }
  const [key = "", ...rest] = path;
  let sub: Schema = { kind: "any" };
  if (s.kind === "object") {
    const additional = s.additional === false || s.additional === undefined ? sub : s.additional;
    sub = s.properties[key]?.schema ?? additional;
  } else if (s.kind === "map") {
    sub = s.values;
  } else if (s.kind === "array") {
    sub = s.items;
  }
  let inner = resolve(sub);
  if (inner.kind === "nullable") {
    inner = resolve(inner.of);
  }
  if (rest.length > 0) {
    container[key] ??= inner.kind === "array" ? [] : {};
    setField(container[key] as Values, inner, rest, value);
  } else if (inner.kind === "array") {
    container[key] ??= [];
    (container[key] as unknown[]).push(scalarValue(inner.items, value));
  } else {
    container[key] = scalarValue(inner, value);
  }
}

async function readResponse(cfg: Config, op: OperationSpec, resp: Response): Promise<unknown> {
  const spec = pick(op, resp);
  if (spec === undefined) {
    throw await unexpected(resp);
  }
  const out: Values = { status: resp.status };
  if (spec.withContentType) {
    out["contentType"] = spec.mediaType;
  }
  const headers: Values = {};
  for (const h of spec.headers ?? []) {
    const raw = resp.headers.get(h.name);
    if (raw === null) {
      if (h.required && cfg.validateResponses) {
        throw new InvalidResponseError(resp.status, `header ${h.name} is required`);
      }
      continue;
    }
    try {
      headers[h.key] = headerValue(h, raw);
    } catch (e) {
      throw new InvalidResponseError(resp.status, `header ${h.name}: ${String(e)}`);
    }
  }
  if (spec.headers !== undefined && spec.headers.length > 0) {
    out["headers"] = headers;
  }
  switch (spec.kind) {
    case "json": {
      let body: unknown;
      try {
        body = JSON.parse(await resp.text());
      } catch (e) {
        throw new InvalidResponseError(resp.status, String(e));
      }
      if (cfg.validateResponses && spec.schema !== undefined) {
        const issues = validate(spec.schema, body, "response");
        if (issues.length > 0) {
          throw new InvalidResponseError(resp.status, issues.map((i) => `${i.pointer}: ${i.message}`).join("; "), issues);
        }
      }
      out["body"] = body;
      break;
    }
    case "text":
      out["body"] = await resp.text();
      break;
    case "binary":
      out["body"] = await resp.blob();
      if (spec.mediaType?.includes("*")) {
        out["contentType"] = resp.headers.get("Content-Type") ?? "";
      }
      break;
    case "byteranges":
      out["body"] = await readByteRanges(resp);
      break;
    case "parts":
      out["body"] = await readParts(cfg, spec.parts!, resp);
      break;
    case "partstream":
      out["items"] = partStream(cfg, spec.parts!, resp);
      break;
    case "jsonl":
      out["items"] = jsonLines(resp);
      break;
    case "sse":
      out["events"] = spec.events === undefined ? serverEvents(resp) : typedEvents(cfg, spec.events, resp);
      break;
    default:
      // Read the empty body so the connection can be reused.
      await resp.arrayBuffer();
  }
  return out;
}

// lines yields the lines of a response as they arrive, ended by LF (a CR
// before it is dropped) or, with cr, also by a CR alone, as in
// text/event-stream.
async function* lines(resp: Response, cr = false): AsyncGenerator<string> {
  if (resp.body === null) {
    return;
  }
  const reader = resp.body.pipeThrough(new TextDecoderStream()).getReader();
  const end = cr ? /\r\n|\r|\n/ : /\r?\n/;
  let buffer = "";
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) {
        break;
      }
      buffer += value;
      let m: RegExpExecArray | null;
      while ((m = end.exec(buffer)) !== null) {
        if (m[0] === "\r" && m.index === buffer.length - 1) {
          // A LF may follow in the next chunk.
          break;
        }
        yield buffer.slice(0, m.index);
        buffer = buffer.slice(m.index + m[0].length);
      }
    }
    if (buffer.endsWith("\r") && cr) {
      buffer = buffer.slice(0, -1);
      yield buffer;
      buffer = "";
    }
    if (buffer !== "") {
      yield buffer;
    }
  } finally {
    // Stopping early cancels the rest of the stream.
    await reader.cancel().catch(() => {});
  }
}

/** The items of a JSON Lines response, as they arrive. */
async function* jsonLines(resp: Response): AsyncGenerator<unknown> {
  for await (const line of lines(resp)) {
    if (line.trim() !== "") {
      yield JSON.parse(line);
    }
  }
}

/** The events of a server-sent events response, as they arrive. An
 * event is dispatched by a blank line, so one the stream ends inside is
 * dropped. */
async function* serverEvents(resp: Response): AsyncGenerator<ServerEvent> {
  let event: ServerEvent = { data: "" };
  let data: string[] = [];
  let pending = false;
  for await (const line of lines(resp, true)) {
    if (line === "") {
      if (pending) {
        event.data = data.join("\n");
        yield event;
      }
      event = { data: "" };
      data = [];
      pending = false;
      continue;
    }
    if (line.startsWith(":")) {
      continue;
    }
    pending = true;
    const colon = line.indexOf(":");
    const field = colon < 0 ? line : line.slice(0, colon);
    const value = colon < 0 ? "" : line.slice(colon + 1).replace(/^ /, "");
    switch (field) {
      case "event":
        event.event = value;
        break;
      case "data":
        data.push(value);
        break;
      case "id":
        event.id = value;
        break;
      case "retry":
        if (/^\d+$/.test(value)) {
          event.retry = Number(value);
        }
        break;
    }
  }
}

/** The events of a typed server-sent events response, as they arrive,
 * their data parsed as its kind says and, with validateResponses,
 * validated. An event that does not parse ends the stream with an
 * InvalidResponseError. */
async function* typedEvents(cfg: Config, spec: EventsSpec, resp: Response): AsyncGenerator<ServerEvent<unknown>> {
  let i = 0;
  for await (const ev of serverEvents(resp)) {
    const kind = eventsSchema(spec, ev.event);
    if (typeof kind === "string") {
      throw new InvalidResponseError(resp.status, `event ${i}: ${kind}`);
    }
    let data: unknown = ev.data;
    if (!kind.text) {
      try {
        data = JSON.parse(ev.data);
      } catch (e) {
        throw new InvalidResponseError(resp.status, `event ${i}: ${String(e)}`);
      }
    }
    if (cfg.validateResponses) {
      const issues = validate(kind.schema, data, "response", `/${i}/data`);
      if (issues.length > 0) {
        throw new InvalidResponseError(resp.status, issues.map((x) => `${x.pointer}: ${x.message}`).join("; "), issues);
      }
    }
    yield { ...ev, data };
    i++;
  }
}

/** A multipart body that is not valid. */
class MultipartError extends Error {}

// boundaryOf returns the boundary of a multipart content type.
function boundaryOf(contentType: string): string | undefined {
  const m = /;\s*boundary\s*=\s*(?:"((?:[^"\\]|\\.)*)"|([^;\s]+))/i.exec(contentType);
  return m === null ? undefined : (m[1]?.replace(/\\(.)/g, "$1") ?? m[2]);
}

/** The bytes of a body, read as they are asked for. */
class ByteReader {
  readonly #reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
  #chunks: Uint8Array[] = [];
  #size = 0;

  constructor(body: ReadableStream<Uint8Array> | null) {
    this.#reader = body?.getReader();
  }

  async #more(): Promise<boolean> {
    if (this.#reader === undefined) {
      return false;
    }
    const { value, done } = await this.#reader.read();
    if (done) {
      return false;
    }
    this.#chunks.push(value);
    this.#size += value.length;
    return true;
  }

  // line returns the next line, with its LF, or what is left of the body.
  async line(): Promise<Uint8Array<ArrayBuffer>> {
    let scanned = 0;
    for (;;) {
      let offset = 0;
      for (const c of this.#chunks) {
        if (offset + c.length > scanned) {
          const i = c.indexOf(10, Math.max(0, scanned - offset));
          if (i >= 0) {
            return this.#take(offset + i + 1);
          }
        }
        offset += c.length;
      }
      scanned = offset;
      if (!(await this.#more())) {
        return this.#take(this.#size);
      }
    }
  }

  // take returns the next n bytes, or undefined if the body ends first.
  async take(n: number): Promise<Uint8Array<ArrayBuffer> | undefined> {
    while (this.#size < n) {
      if (!(await this.#more())) {
        return undefined;
      }
    }
    return this.#take(n);
  }

  #take(n: number): Uint8Array<ArrayBuffer> {
    const out = new Uint8Array(n);
    let filled = 0;
    while (filled < n) {
      const c = this.#chunks[0]!;
      const k = Math.min(c.length, n - filled);
      out.set(c.subarray(0, k), filled);
      filled += k;
      if (k === c.length) {
        this.#chunks.shift();
      } else {
        this.#chunks[0] = c.subarray(k);
      }
    }
    this.#size -= n;
    return out;
  }

  async cancel(): Promise<void> {
    await this.#reader?.cancel().catch(() => {});
  }
}

interface RawPart {
  readonly header: Headers;
  readonly data: Uint8Array<ArrayBuffer>;
}

// rawParts yields the parts of a multipart body as they arrive. A part
// with a Content-Length is complete once its data has arrived, others
// once the delimiter after them has. As in Go's mime/multipart, a
// preamble may come before the first delimiter, line ends are LF if that
// delimiter's is, and a body that ends in the headers of a part ends
// there. A body that is not valid throws a MultipartError.
async function* rawParts(body: ReadableStream<Uint8Array> | null, contentType: string): AsyncGenerator<RawPart> {
  const boundary = boundaryOf(contentType);
  if (boundary === undefined || boundary === "") {
    throw new MultipartError("multipart body without a boundary");
  }
  const r = new ByteReader(body);
  const ascii = new TextDecoder("latin1");
  const utf8 = new TextDecoder();
  const dash = "--" + boundary;
  let nl = "\r\n";
  // delimiter says whether line is a delimiter, and whether the last.
  const delimiter = (line: Uint8Array): "next" | "final" | undefined => {
    if (line[0] !== 45 || line[1] !== 45) {
      return undefined;
    }
    const s = ascii.decode(line);
    if (!s.startsWith(dash)) {
      return undefined;
    }
    const rest = s.slice(dash.length);
    if (rest.startsWith("--")) {
      const after = rest.slice(2).replace(/^[ \t]+/, "");
      if (after === "" || after === nl) {
        return "final";
      }
    }
    return rest.replace(/^[ \t]+/, "") === nl ? "next" : undefined;
  };
  const endsLine = (line: Uint8Array) => line[line.length - 1] === 10;
  try {
    for (;;) {
      const line = await r.line();
      if (ascii.decode(line).slice(dash.length).replace(/^[ \t]+/, "") === "\n" && ascii.decode(line).startsWith(dash)) {
        nl = "\n";
      }
      const d = delimiter(line);
      if (d === "final") {
        return;
      }
      if (d === "next") {
        break;
      }
      if (!endsLine(line)) {
        throw new MultipartError("the body ends before its first boundary");
      }
    }
    for (;;) {
      const header = new Headers();
      let name = "";
      for (;;) {
        const line = await r.line();
        if (!endsLine(line)) {
          return;
        }
        const s = utf8.decode(line).replace(/\r?\n$/, "");
        if (s === "") {
          break;
        }
        if ((s[0] === " " || s[0] === "\t") && name !== "") {
          // A continuation of the header before.
          const values = header.get(name) ?? "";
          header.set(name, values + " " + s.trim());
          continue;
        }
        const colon = s.indexOf(":");
        if (colon <= 0) {
          throw new MultipartError(`invalid part header line ${JSON.stringify(s)}`);
        }
        name = s.slice(0, colon).trim();
        try {
          header.append(name, s.slice(colon + 1).trim());
        } catch (e) {
          throw new MultipartError(`invalid part header ${JSON.stringify(name)}: ${String(e)}`);
        }
      }
      const length = header.get("Content-Length");
      if (length !== null) {
        if (!/^\d+$/.test(length)) {
          throw new MultipartError(`invalid Content-Length ${JSON.stringify(length)}`);
        }
        const data = await r.take(Number(length));
        if (data === undefined) {
          throw new MultipartError("the body ends inside a part");
        }
        yield { header, data };
        const end = ascii.decode(await r.line()) === nl ? delimiter(await r.line()) : undefined;
        if (end === undefined) {
          throw new MultipartError("a part does not end at its Content-Length");
        }
        if (end === "final") {
          return;
        }
        continue;
      }
      const lines: Uint8Array<ArrayBuffer>[] = [];
      for (;;) {
        const line = await r.line();
        const last = lines[lines.length - 1];
        const d = delimiter(line);
        if (d !== undefined && (last === undefined || ascii.decode(last).endsWith(nl))) {
          // The line end before the delimiter belongs to it.
          if (last !== undefined) {
            lines[lines.length - 1] = last.subarray(0, last.length - nl.length);
          }
          yield { header, data: new Uint8Array(await new Blob(lines).arrayBuffer()) };
          if (d === "final") {
            return;
          }
          break;
        }
        if (!endsLine(line)) {
          throw new MultipartError("the body ends inside a part");
        }
        lines.push(line);
      }
    }
  } finally {
    // Stopping early cancels the rest of the body.
    await r.cancel();
  }
}

// readIssues checks a part read at index i against its encoding: the
// content types it may have, and its headers.
function readIssues(spec: PartsSpec, raw: RawPart, i: number): Issue[] {
  const enc = encodingAt(spec, i);
  const ct = raw.header.get("Content-Type");
  const issues: Issue[] = [];
  if (ct !== null && enc.contentTypes !== undefined && enc.contentTypes.length > 0) {
    const mt = ct.split(";")[0]!.trim().toLowerCase();
    if (!enc.contentTypes.some((d) => mediaMatches(d, mt))) {
      issues.push({ pointer: `/${i}`, message: `content type ${JSON.stringify(ct)} is not allowed; expected ${enc.contentTypes.join(", ")}` });
    }
  }
  return [...issues, ...headerIssues(enc, raw.header, `/${i}`, "response")];
}

// partValue returns the item a part is: a Blob (a File, if the part names
// one), its text, or its body as JSON, in a Part if spec says.
function partValue(spec: PartItemSpec, raw: RawPart): unknown {
  let value: unknown;
  const utf8 = new TextDecoder();
  switch (spec.kind) {
    case "file": {
      const type = raw.header.get("Content-Type") ?? "";
      const name = /filename\s*=\s*(?:"((?:[^"\\]|\\.)*)"|([^;\s]+))/i.exec(raw.header.get("Content-Disposition") ?? "");
      value =
        name !== null && typeof File !== "undefined"
          ? new File([raw.data], (name[1]?.replace(/\\(.)/g, "$1") ?? name[2])!, { type })
          : new Blob([raw.data], { type });
      break;
    }
    case "text":
      value = utf8.decode(raw.data);
      break;
    default:
      value = JSON.parse(utf8.decode(raw.data));
  }
  return spec.part ? ({ header: raw.header, value } satisfies Part<unknown>) : value;
}

// decodePart returns the item of raw, the part at index i, of item, after
// checking it against its encoding and, with validateResponses, its
// schema. A problem throws an InvalidResponseError.
function decodePart(cfg: Config, spec: PartsSpec, item: PartItemSpec, raw: RawPart, i: number, status: number): unknown {
  const fail = (issues: Issue[]) => new InvalidResponseError(status, issues.map((x) => `${x.pointer}: ${x.message}`).join("; "), issues);
  const encoding = readIssues(spec, raw, i);
  if (encoding.length > 0) {
    throw fail(encoding);
  }
  let value: unknown;
  try {
    value = partValue(item, raw);
  } catch (e) {
    throw fail([{ pointer: `/${i}`, message: String(e) }]);
  }
  if (cfg.validateResponses) {
    const issues = validate(item.schema, item.part ? (value as Part<unknown>).value : value, "response", `/${i}`);
    if (issues.length > 0) {
      throw fail(issues);
    }
  }
  return value;
}

// multipartFailure turns an invalid body into an InvalidResponseError.
function multipartFailure(e: unknown, status: number): unknown {
  return e instanceof MultipartError ? new InvalidResponseError(status, `invalid multipart body: ${e.message}`) : e;
}

/** A response of positional parts: an array of its items, or an object
 * with the positions of a tuple and rest for the parts after them. */
async function readParts(cfg: Config, spec: PartsSpec, resp: Response): Promise<unknown> {
  const items: unknown[] = [];
  const tuple: Values = {};
  const fail = (message: string, pointer: string) => new InvalidResponseError(resp.status, `${pointer}: ${message}`, [{ pointer, message }]);
  let i = 0;
  try {
    for await (const raw of rawParts(resp.body, resp.headers.get("Content-Type") ?? "")) {
      const position = spec.prefix?.[i];
      const item = position ?? spec.item;
      if (item === undefined) {
        throw fail(`unexpected part: the body has at most ${spec.prefix?.length ?? 0}`, `/${i}`);
      }
      const value = decodePart(cfg, spec, item, raw, i, resp.status);
      if (position !== undefined) {
        tuple[position.key] = value;
      } else {
        items.push(value);
      }
      i++;
    }
  } catch (e) {
    throw multipartFailure(e, resp.status);
  }
  const missing = spec.prefix?.findIndex((p, n) => n >= i && !p.optional) ?? -1;
  if (missing >= 0) {
    throw fail("part is missing", `/${missing}`);
  }
  if (cfg.validateResponses) {
    const issues = validate(countSchema(spec), new Array(i), "response");
    if (issues.length > 0) {
      throw new InvalidResponseError(resp.status, issues.map((x) => `${x.pointer}: ${x.message}`).join("; "), issues);
    }
  }
  if (spec.prefix === undefined) {
    return items;
  }
  if (spec.item !== undefined) {
    tuple["rest"] = items;
  }
  return tuple;
}

/** The items of a response of streamed positional parts, as they arrive.
 * A part that is not valid ends the stream with an InvalidResponseError. */
async function* partStream(cfg: Config, spec: PartsSpec, resp: Response): AsyncGenerator<unknown> {
  let i = 0;
  try {
    for await (const raw of rawParts(resp.body, resp.headers.get("Content-Type") ?? "")) {
      yield decodePart(cfg, spec, spec.item!, raw, i, resp.status);
      i++;
    }
  } catch (e) {
    throw multipartFailure(e, resp.status);
  }
}

// contentRange parses a Content-Range, "bytes first-last/size", with a
// size of "*" for an unknown one, -1.
function contentRange(s: string): { start: number; end: number; size: number } | undefined {
  const m = /^\s*bytes\s+(\d+)-(\d+)\/(\d+|\*)\s*$/i.exec(s);
  if (m === null) {
    return undefined;
  }
  const [start, end, size] = [Number(m[1]), Number(m[2]), m[3] === "*" ? -1 : Number(m[3])];
  return start > end || (size >= 0 && end >= size) ? undefined : { start, end, size };
}

/** The ranges of a multipart/byteranges response, each read from its
 * part's Content-Range and checked against its data. */
async function readByteRanges(resp: Response): Promise<ByteRange[]> {
  const ranges: ByteRange[] = [];
  try {
    for await (const raw of rawParts(resp.body, resp.headers.get("Content-Type") ?? "")) {
      const i = ranges.length;
      const cr = raw.header.get("Content-Range");
      const r = cr === null ? undefined : contentRange(cr);
      const fail = (message: string) => new InvalidResponseError(resp.status, `/${i}: ${message}`, [{ pointer: `/${i}`, message }]);
      if (r === undefined) {
        throw fail(cr === null ? 'part header "Content-Range" is missing' : `Content-Range ${JSON.stringify(cr)} is not a range of bytes`);
      }
      if (raw.data.length !== r.end - r.start + 1) {
        throw fail(`bytes ${r.start}-${r.end} hold ${raw.data.length} bytes of data`);
      }
      const contentType = raw.header.get("Content-Type") ?? "";
      ranges.push({ ...r, contentType, data: new Blob([raw.data], { type: contentType }) });
    }
  } catch (e) {
    throw multipartFailure(e, resp.status);
  }
  return ranges;
}
